1	#pragma once
2	#include "VariableLengthBlockProtocol.h"
3	#include <cstdint>
4	
5	/**
6	 * Block title values for KWP-71.
7	 * There are some ECUs that appear to be using KWP-71 for communication, but
8	 * that use non-standard block titles (probably for obfuscation of the interface).
9	 * These include the Ferrari F355 Motronic 5.2, which apparently responds to a
10	 * block 0x3A request with fault code data.
11	 */
12	enum class KWP71BlockType : uint8_t
13	{
14	  RequestID         = 0x00,
15	  ReadRAM           = 0x01,
16	  WriteRAM          = 0x02,
17	  ReadROM           = 0x03,
18	  ActivateActuator  = 0x04,
19	  EraseTroubleCodes = 0x05,
20	  Disconnect        = 0x06,
21	  ReadTroubleCodes  = 0x07,
22	  ReadADCChannel    = 0x08,
23	  Empty             = 0x09,
24	  NACK              = 0x0A,
25	  NotSupported      = 0x0B,
26	  ReadParamData     = 0x10,
27	  RecordParamData   = 0x11,
28	  RequestSnapshot   = 0x12,
29	  ReadEEPROM        = 0x19,
30	  WriteEEPROM       = 0x1A,
31	  ParamRecordConf   = 0xEB,
32	  ParametricData    = 0xEC,
33	  EEPROMContent     = 0xEF,
34	  Snapshot          = 0xF4,
35	  InfoString        = 0xF6,
36	  ADCValue          = 0xFB,
37	  BinaryData        = 0xFC,
38	  RAMContent        = 0xFD,
