// minRange: the smallest y-span the axis may show. Without it, autoscaling on a
// near-constant series magnifies one count of sensor quantization into a
// dramatic-looking spike -- battery resolves to 0.068 V per count and intake air
// to 0.65 °C, so a flat reading would otherwise look violently unstable.
const SENSORS = [
  {key:'rpm',             label:'Régimen',            unit:'rpm', dec:0, minRange:300},
  {key:'coolant_temp',    label:'Refrigerante',       unit:'°C',  dec:1, minRange:10},
  {key:'intake_air_temp', label:'Aire admisión',      unit:'°C',  dec:1, minRange:10},
  {key:'battery',         label:'Batería',            unit:'V',   dec:2, minRange:2},
  {key:'load',            label:'Carga (inyección)',  unit:'ms',  dec:2, minRange:2},
];

