import re
p='e36obd/static/dashboard.html'
s=open(p).read()

# pass minRange through both chart call sites
s=s.replace("lineChart($('#lc-' + s.key), pts, {dec: s.dec, unit: s.unit, xlabel: null});",
            "lineChart($('#lc-' + s.key), pts, {dec: s.dec, unit: s.unit, minRange: s.minRange, xlabel: null});")
s=s.replace("lineChart($('#hc-' + s.key), pts, {dec: s.dec, unit: s.unit, height: 132,\n      xlo: '0:00', xhi: fmt(t[t.length-1]), xlabel: fmt});",
            "lineChart($('#hc-' + s.key), pts, {dec: s.dec, unit: s.unit, height: 132,\n      minRange: s.minRange, xlo: '0:00', xhi: fmt(t[t.length-1]), xlabel: fmt});")

# hide the live chart grid entirely until there is data to draw
s=s.replace("""  const box = $('#livecharts');
  if (!box.children.length) {""",
"""  const box = $('#livecharts');
  const hasData = live[SENSORS[0].key].length > 0;
  box.hidden = !hasData;
  $('#nolive').hidden = hasData;
  if (!hasData) return;
  if (!box.children.length) {""")

s=s.replace('<div id="livecharts" class="charts" style="margin-top:12px"></div>',
 '<div id="livecharts" class="charts" style="margin-top:12px"></div>\n'
 '  <div id="nolive" class="empty" style="margin-top:12px">Sin ECU conectada — los gráficos en vivo aparecen al conectar el cable con el contacto puesto.</div>')

# theme override via ?theme=light|dark, so both modes can be inspected
s=s.replace("(async function init() {",
"""(async function init() {
  const t = new URLSearchParams(location.search).get('theme');
  if (t === 'light' || t === 'dark') document.documentElement.dataset.theme = t;""")
open(p,'w').write(s)
print("ok")
PY
