/* --------------------------- actions -------------------------- */
async function act(action, params) {
  const r = await (await fetch('/api/action', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({action, params: params || {}})
  })).json();
  if (!r.ok) alert(r.error || 'la acción falló');
}

let recording = null;
$('#btn-record').onclick = () =>
  act(recording ? 'record_stop' : 'record_start', {});
$('#btn-faults').onclick   = () => act('refresh_faults');
$('#btn-snapshot').onclick = () => act('snapshot', {note: 'desde el dashboard'});
$('#btn-ds2').onclick      = () => act('ds2_scan');

const EV_ICON = {good: '✓', warn: '!', bad: '✕', info: '·'};
function renderEvents(evs) {
  const box = $('#events');
  box.classList.toggle('show', !!(evs && evs.length));
  if (!evs || !evs.length) return;
  box.innerHTML = evs.map(e => `<div class="ev ev-${e.kind}">
      <time>${e.t}</time><span class="ic">${EV_ICON[e.kind] || '·'}</span>
      <span>${e.text.replace(/</g,'&lt;')}</span></div>`).join('');
}

/* ----------------------------- EGS ---------------------------- */
// The transmission module speaks DS2, not the KWP71 the DME uses -- which is
// why the 5-baud address sweep never found it. We show whatever the DS2 probe
// returns raw, because the EGS fault-code byte layout is not decoded yet;
// inventing a decode here would be worse than showing hex.
function renderEgs(mods, connected) {
  const box = $('#egs');
  if (mods === undefined || mods === null) {
    box.innerHTML = `<div class="empty">
      Todavía no se buscó. El EGS habla <b>DS2</b> (9600 8E1, sin init), no el
      KWP71 del motor — por eso nunca apareció en los barridos de 5 baudios.<br>
      Con el contacto puesto, tocá <b>Buscar EGS / módulos DS2</b>.</div>`;
    return;
  }
  if (!mods.length) {
    box.innerHTML = `<div class="empty">
      Ningún módulo DS2 respondió.<br>
      <span class="muted">Puede que el EGS de este año no exponga diagnóstico serie,
      o que use otra dirección. Dirección esperada: 0x32.</span></div>`;
    return;
  }
  box.innerHTML = mods.map(m => `<div class="mod">
      <div><span class="addr">${m.address}</span>
        ${m.id ? '— ' + m.id.replace(/</g,'&lt;') : ''}</div>
      <div class="hex">id: ${m.raw}</div>
      ${m.faults ? `<div class="hex">fallas (sin decodificar): ${m.faults}</div>`
                 : `<div class="muted" style="margin-top:5px">sin memoria de fallas legible</div>`}
    </div>`).join('');
}

/* ---------------------------- poll ---------------------------- */

