python3 - <<'PY'
import re
p='e36obd/static/dashboard.html'
s=open(p).read()

new_css = '''
  /* ------------------------------------------------------------------
     E36 instrument-cluster look: amber backlighting on warm near-black,
     monospace segment-style numerals, a soft bloom on lit elements.

     This design deliberately commits to a single dark look -- an
     instrument cluster is dark by nature, so there is no light mode to
     step. Every colour is painted explicitly rather than inherited.

     The chart series colour (#d96f14) is the brightest amber that still
     sits inside the dark-mode lightness band (OKLCH L 0.48-0.67) and
     clears 3:1 against this surface -- validated, not eyeballed. Text
     amber runs brighter because text is judged on WCAG contrast instead.
     ------------------------------------------------------------------ */
  .viz-root {
    color-scheme: dark;
    --surface-0:      #0b0806;   /* dashboard black */
    --surface-1:      #14100c;   /* instrument panel */
    --surface-2:      #1c1610;   /* raised control */
    --border:         #2e2318;
    --border-lit:     #4a3520;
    --text-primary:   #ffb37a;   /* lit amber */
    --text-secondary: #c98a52;
    --text-muted:     #8a5f3a;
    --series-1:       #d96f14;   /* validated chart amber */
    --grid:           #241a12;
    --good:           #0ca30c;
    --warning:        #fab219;
    --serious:        #ec835a;
    --critical:       #d03b3b;
    --glow:           0 0 14px rgba(217,111,20,.40);
    --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  }

  * { box-sizing: border-box; }
  body { margin: 0; background: #000; }
  .viz-root {
    background:
      radial-gradient(120% 80% at 50% -10%, #17110b 0%, var(--surface-0) 62%);
    color: var(--text-primary);
    font: 13px/1.5 var(--mono);
    letter-spacing: .02em;
    min-height: 100vh;
    padding: 26px 20px 60px;
  }
  .wrap { max-width: 1180px; margin: 0 auto; }

  header { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-bottom: 3px; }
  h1 { font-size: 16px; font-weight: 600; margin: 0; letter-spacing: .13em;
       text-transform: uppercase; color: var(--text-primary); text-shadow: var(--glow); }
  .sub { color: var(--text-muted); font-size: 11.5px; letter-spacing: .06em; }
  h2 { font-size: 11px; font-weight: 600; margin: 30px 0 11px; letter-spacing: .19em;
       text-transform: uppercase; color: var(--text-muted); }

  .status { display: inline-flex; align-items: center; gap: 7px; padding: 3px 11px 3px 9px;
            border: 1px solid var(--border-lit); border-radius: 3px; font-size: 11px;
            letter-spacing: .1em; text-transform: uppercase;
            background: var(--surface-1); color: var(--text-secondary); }
  .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--text-muted); flex: none; }
  .dot.on  { background: var(--good);     box-shadow: 0 0 9px var(--good); }
  .dot.off { background: var(--critical); box-shadow: 0 0 9px var(--critical); }

  /* Segment-readout tiles, after the OBC display */
  .tiles { display: grid; gap: 9px; grid-template-columns: repeat(auto-fit, minmax(152px, 1fr)); }
  .tile { background: linear-gradient(180deg, #16110c, #100c08);
          border: 1px solid var(--border); border-radius: 4px; padding: 11px 13px 12px; }
  .tile .label { font-size: 9.5px; text-transform: uppercase; letter-spacing: .17em;
                 color: var(--text-muted); margin-bottom: 6px; }
  .tile .value { font-size: 27px; font-weight: 500; letter-spacing: .01em;
                 font-variant-numeric: tabular-nums; color: var(--text-primary);
                 text-shadow: var(--glow); }
  .tile .unit { font-size: 12px; font-weight: 400; color: var(--text-muted);
                margin-left: 4px; text-shadow: none; letter-spacing: .08em; }

  .charts { display: grid; gap: 10px; grid-template-columns: repeat(auto-fit, minmax(330px, 1fr)); }
  .card { background: var(--surface-1); border: 1px solid var(--border);
          border-radius: 4px; padding: 12px 14px 6px; }
  .card h3 { margin: 0 0 2px; font-size: 10.5px; font-weight: 600; letter-spacing: .16em;
             text-transform: uppercase; color: var(--text-secondary); }
  .card .cur { font-size: 10.5px; color: var(--text-muted); letter-spacing: .06em;
               font-variant-numeric: tabular-nums; margin-bottom: 6px; }
  svg { display: block; width: 100%; overflow: visible; }
  .gridline { stroke: var(--grid); stroke-width: 1; }
  .axis-text { fill: var(--text-muted); font-size: 9.5px; font-family: var(--mono);
               font-variant-numeric: tabular-nums; letter-spacing: .04em; }
  .line { fill: none; stroke: var(--series-1); stroke-width: 2;
          stroke-linejoin: round; stroke-linecap: round;
          filter: drop-shadow(0 0 4px rgba(217,111,20,.55)); }
  .marker { fill: var(--series-1); stroke: var(--surface-1); stroke-width: 2; }
  .crosshair { stroke: var(--text-muted); stroke-width: 1; stroke-dasharray: 3 3; }

  /* Buttons echo the OBC's bezelled key row */
  .controls { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-bottom: 11px; }
  select, button { font: inherit; font-family: var(--mono); font-size: 11px;
                   letter-spacing: .12em; text-transform: uppercase;
                   padding: 7px 13px; border-radius: 3px;
                   border: 1px solid var(--border-lit); background: var(--surface-2);
                   color: var(--text-secondary); }
  button { cursor: pointer; transition: color .12s, border-color .12s, box-shadow .12s; }
  button:hover:not(:disabled) { color: var(--text-primary); border-color: var(--series-1);
                                box-shadow: 0 0 12px rgba(217,111,20,.22); }
  button.primary { color: var(--text-primary); border-color: var(--series-1); }
  button.rec { color: #ff8a86; border-color: var(--critical);
               box-shadow: 0 0 12px rgba(208,59,59,.28); }
  button:disabled { opacity: .34; cursor: not-allowed; }

  .events { background: #0d0a07; border: 1px solid var(--border); border-radius: 4px;
            padding: 7px 12px; max-height: 158px; overflow-y: auto; font-size: 11px;
            display: none; }
  .events.show { display: block; }
  .ev { display: grid; grid-template-columns: 66px 14px 1fr; gap: 9px; padding: 3px 0;
        border-bottom: 1px solid #1a130d; color: var(--text-secondary); }
  .ev:last-child { border-bottom: 0; }
  .ev time { color: var(--text-muted); font-variant-numeric: tabular-nums; }
  .ev .ic { text-align: center; }
  .ev-good .ic { color: var(--good); } .ev-warn .ic { color: var(--warning); }
  .ev-bad  .ic { color: var(--critical); } .ev-info .ic { color: var(--text-muted); }

  .faults { display: grid; gap: 9px; }
  .fault { background: var(--surface-1); border: 1px solid var(--border); border-radius: 4px;
           padding: 12px 14px; display: grid; grid-template-columns: auto 1fr; gap: 12px;
           align-items: start; }
  .fault .icon { font-size: 15px; line-height: 1.3; }
  .fault .code { font-weight: 600; color: var(--text-primary); letter-spacing: .06em; }
  .fault .badge { display: inline-block; font-size: 9.5px; font-weight: 600; padding: 2px 7px;
                  border-radius: 2px; border: 1px solid currentColor; margin-left: 8px;
                  letter-spacing: .14em; vertical-align: 1px; }
  .fault .meta { color: var(--text-muted); font-size: 11px; margin-top: 6px; line-height: 1.65; }
  .fault .meta b { color: var(--text-secondary); font-weight: 600; font-variant-numeric: tabular-nums; }
  .f-critical { color: var(--critical); } .f-warning { color: var(--warning); }
  .f-serious  { color: var(--serious); }  .f-good    { color: var(--good); }

  .mod { background: var(--surface-1); border: 1px solid var(--border-lit); border-radius: 4px;
         padding: 12px 14px; margin-bottom: 9px; }
  .mod .addr { font-weight: 600; color: var(--text-primary); letter-spacing: .08em;
               font-variant-numeric: tabular-nums; }
  .mod .hex { font-size: 11px; color: var(--text-muted); word-break: break-all; margin-top: 5px;
              letter-spacing: .05em; }

  table { border-collapse: collapse; width: 100%; font-size: 11px;
          font-variant-numeric: tabular-nums; }
  th, td { text-align: right; padding: 5px 9px; border-bottom: 1px solid #1a130d;
           color: var(--text-secondary); }
  th:first-child, td:first-child { text-align: left; }
  th { color: var(--text-muted); font-weight: 600; font-size: 9.5px;
       text-transform: uppercase; letter-spacing: .14em; }
  .scroll { overflow-x: auto; background: var(--surface-1);
            border: 1px solid var(--border); border-radius: 4px; padding: 4px 14px 10px; }

  .muted { color: var(--text-muted); font-size: 11px; letter-spacing: .06em; }
  .empty { background: var(--surface-1); border: 1px dashed var(--border-lit); border-radius: 4px;
           padding: 22px; color: var(--text-muted); text-align: center; font-size: 11.5px;
           line-height: 1.8; }
  .empty b { color: var(--text-secondary); }
  .tip { position: fixed; pointer-events: none; background: var(--surface-2);
         color: var(--text-primary); border: 1px solid var(--border-lit); border-radius: 3px;
         padding: 6px 9px; font-size: 11px; font-family: var(--mono);
         font-variant-numeric: tabular-nums; letter-spacing: .04em;
         box-shadow: 0 0 18px rgba(0,0,0,.7); opacity: 0;
         transition: opacity .1s; z-index: 20; white-space: nowrap; }
'''

s = re.sub(r'<style>.*?</style>', '<style>' + new_css + '</style>', s, flags=re.S)
open(p,'w').write(s)
print("css reemplazado,", len(s), "bytes")
