p='e36obd/static/dashboard.html'; s=open(p).read()

old = s[s.index("const GS = 300;"):s.index("function buildCluster()")]
new = '''const GS = 300;                                // viewBox de todos los diales

/* Geometría según MIL-STD-1472F §5.2.3, que es de donde salen las convenciones
   que respetan Bosch, MoTeC, AiM y Stack:

   · La jerarquía de marcas se codifica en LARGO, no en color ni en grosor.
     Mayor ≈ 2,4× la menor; los anchos casi iguales bajo iluminación normal.
   · Los numerales van del lado de las marcas OPUESTO a la aguja (§5.2.3.2.4.4).
     Adentro del anillo la aguja los taparía al pasar.
   · La aguja llega hasta, pero no pisa, la marca más corta (§5.2.3.1.7), con
     punta PLANA del ancho de una marca menor y cono de 40° incluidos.
   · La cola de la aguja va del color del fondo — o sea, invisible. Ningún
     instrumento real (Stack, VDO, Bosch) muestra contrapeso.
   · El límite es una LÍNEA radial a pleno; el rango de precaución es un arco
     (14 CFR 25.1549, que es de donde viene la convención de la zona roja). */
const R_NUM   = GS * 0.447;   // numerales, por FUERA de las marcas
const R_TICK  = GS * 0.400;   // extremo exterior de las marcas
const L_MINOR = GS * 0.024;   // largo de marca menor
const L_MAJOR = L_MINOR * 2.4;
const R_TIP   = R_TICK - L_MINOR - GS * 0.010;   // punta, con luz antes de la marca
const R_HUB   = GS * 0.045;

function dialSVG(s) {
  const c = GS / 2;
  const ang = v => A0 + (v - s.min) / (s.max - s.min) * SWEEP;
  const limit = s.redline !== undefined ? s.redline
              : (s.warnHi !== undefined ? s.warnHi : null);
  let g = '';

  // Rango de precaución: arco por fuera de las marcas, a pleno.
  if (limit !== null)
    g += `<path class="gauge-zone" d="${arc(c, c, R_TICK + GS*0.022, ang(limit), ang(s.max))}"
          stroke-width="${(GS*0.013).toFixed(1)}"/>`;

  const steps = Math.round((s.max - s.min) / s.minor);
  for (let i = 0; i <= steps; i++) {
    const v = s.min + i * s.minor, a = ang(v);
    const maj = Math.abs(v / s.major - Math.round(v / s.major)) < 1e-6;
    const len = maj ? L_MAJOR : L_MINOR;
    const [x1, y1] = pol(c, c, R_TICK, a);
    const [x2, y2] = pol(c, c, R_TICK - len, a);
    // Dentro del rango de precaución las marcas se recolorean, que es lo que
    // hace Bosch, en vez de tapar la escala con una banda.
    const hot = limit !== null && v >= limit;
    g += `<line class="${hot ? 'tick-hot' : (maj ? 'tick-maj' : 'tick')}"
          x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"
          stroke-width="${maj ? 1.6 : 1.2}"/>`;
    if (maj) {
      const [nx, ny] = pol(c, c, R_NUM, a);
      const lbl = s.max > 1000 ? String(Math.round(v / 1000)) : String(v);
      g += `<text class="tick-num" x="${nx.toFixed(1)}" y="${ny.toFixed(1)}"
            style="font-size:${(GS*0.062).toFixed(1)}px">${lbl}</text>`;
    }
  }

  // El límite propiamente dicho es una línea, no una banda.
  if (limit !== null) {
    const a = ang(limit);
    const [lx1, ly1] = pol(c, c, R_TICK + GS*0.030, a);
    const [lx2, ly2] = pol(c, c, R_TICK - L_MAJOR, a);
    g += `<line class="limit-line" x1="${lx1.toFixed(1)}" y1="${ly1.toFixed(1)}"
          x2="${lx2.toFixed(1)}" y2="${ly2.toFixed(1)}" stroke-width="2.2"/>`;
  }

  g += `<text class="gauge-val" id="gv-${s.key}" x="${c}" y="${(c + GS*0.385).toFixed(0)}"
        style="font-size:${(GS*0.115).toFixed(1)}px">—</text>`;
  g += `<text class="gauge-unit" x="${c}" y="${(c + GS*0.462).toFixed(0)}"
        style="font-size:${(GS*0.04).toFixed(1)}px">${s.unit}${s.max > 1000 ? ' ×1000' : ''}</text>`;

  // Aguja: cuerpo de ancho constante, punta plana del ancho de una marca menor,
  // cono de 40° incluidos. Sin cola. Definida apuntando hacia arriba y rotada.
  const wS = 2.0, wT = 0.6;
  const taper = (wS - wT) / Math.tan(20 * Math.PI / 180);
  const pts = [
    [c - wS, c - R_HUB], [c - wS, c - R_TIP + taper], [c - wT, c - R_TIP],
    [c + wT, c - R_TIP], [c + wS, c - R_TIP + taper], [c + wS, c - R_HUB],
  ].map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(' ');
  g += `<polygon class="needle" id="gn-${s.key}" points="${pts}"
        transform="rotate(${A0} ${c} ${c})"/>`;
  g += `<circle class="hub" cx="${c}" cy="${c}" r="${R_HUB.toFixed(1)}" stroke-width="1.4"/>`;
  return `<svg class="plot" viewBox="0 0 ${GS} ${GS}">${g}</svg>`;
}

'''
