s = s.replace("""      segs[i].className = i < lit ? (bad ? 'warn' : 'on') : '';""",
"""      segs[i].className = i < lit
        ? (bad ? 'warn' : 'on') + (i === lit - 1 ? ' lead' : '')
        : '';""")

# Bloom solo en el readout principal. La norma admite dos niveles de brillo,
