  ".led.on  i { background: var(--good); }"),
 (".led.off i { background: var(--crit); box-shadow: 0 0 8px var(--crit); }",
  ".led.off i { background: var(--crit); }"),
 ("""background: var(--crit); box-shadow: 0 0 9px var(--crit);
             animation: pulse""", "background: var(--crit); animation: pulse"),
 ("box-shadow: 0 0 12px rgba(250,178,25,.13); }", "}"),
 ("box-shadow: 0 0 12px rgba(208,59,59,.16); }", "}"),
 ("font-size: 15px; color: var(--ink); text-shadow: var(--glow-soft); }",
  "font-size: 15px; color: var(--ink); }"),
 ("margin-top: 3px; text-shadow: var(--glow-soft); }", "margin-top: 3px; }"),
 (".gauge-cell .cap { font-size: 9.5px; letter-spacing: .22em;",
  ".gauge-cell .cap { font-size: 9.5px; letter-spacing: .12em;"),
]
