node - <<'JS'
// Réplica de la lógica de búsqueda guiada, sin DOM.
let ramCand = null, ramBase = null, ramUndo = [];
function filter(mode, b) {
  if (!ramBase || ramBase.length !== b.length) { ramBase = b.slice(); ramCand = new Set(b.map((_, i) => i)); return; }
  if (ramCand === null) ramCand = new Set(b.map((_, i) => i));
  ramUndo.push(new Set(ramCand));
  const keep = new Set();
  ramCand.forEach(i => {
    const d = b[i] - ramBase[i];
    if ((mode === 'up' && d > 0) || (mode === 'down' && d < 0)
     || (mode === 'chg' && d !== 0) || (mode === 'same' && d === 0)) keep.add(i);
  });
  ramCand = keep; ramBase = b.slice();
}
function mark(b) { ramBase = b.slice(); if (ramCand === null) ramCand = new Set(b.map((_, i) => i)); }

// 8 bytes. idx 3 = "TPS" (sigue al acelerador). idx 5 = contador libre.
// idx 1 = ruido que sube y baja al azar. El resto, constantes.
const f = (tps, ctr, noise) => [10, noise, 99, tps, 7, ctr, 0, 42];
let ctr = 0;
mark(f(20, ctr++, 50));
filter('up',   f(200, ctr++, 55));   // piso el acelerador
console.log('tras "subieron" :', [...ramCand].join(','));
filter('down', f(20,  ctr++, 51));   // suelto
console.log('tras "bajaron"  :', [...ramCand].join(','));
filter('up',   f(180, ctr++, 49));   // piso otra vez
console.log('tras "subieron" :', [...ramCand].join(','));
const ok = ramCand.size === 1 && ramCand.has(3);
console.log('\nundo disponible :', ramUndo.length, 'paso(s)');
console.log(ok ? 'BUSQUEDA GUIADA OK — converge al byte 3 (el TPS)' : 'FALLA: quedaron ' + [...ramCand]);
process.exit(ok ? 0 : 1);
