    g += `<path class="${i === 0 ? 'line' : 'line-b'}" d="${d}"/>`;""",
"""  // Un hueco en los datos NO es una línea recta. Interpolarlo dibuja una
   // lectura firme donde en realidad no hubo comunicación -- que es
   // exactamente lo contrario de lo que un instrumento de diagnóstico debe
   // hacer. Se corta el trazo y se marca el hueco.
  const gapsOf = pts => {
    if (pts.length < 3) return { limit: Infinity, spans: [] };
    const dt = pts.slice(1).map((p, i) => p.x - pts[i].x).sort((a, b) => a - b);
    const med = dt[Math.floor(dt.length / 2)] || 0;
    const limit = Math.max(med * 3, med + 1e-9);
