      return `${brk ? 'M' : 'L'}${sx(p.x).toFixed(1)},${sy(p.y).toFixed(1)}`;
    }).join('');
    g += `<path class="${i === 0 ? 'line' : 'line-b'}" d="${d}"/>`;""")

