"""  <h2>Modo foco · resolución temporal</h2>
  <div class="empty" style="text-align:left; margin-bottom:10px">
    El enlace no es de 1 Hz — es de 1 Hz <b>para once bytes</b>. KWP71 acusa cada byte
    con su inverso, así que el costo en cable es ~2× el payload. Enfocando <b>una sola
    dirección</b> se sacan varios Hz, y esa es la única palanca real para ver un evento
    de décimas de segundo.<br>
    El servidor guarda las muestras en un anillo y las entrega en lote, así que muestrear
    rápido sirve aunque el navegador consulte una vez por segundo.
  </div>
  <div class="row" style="margin-bottom:10px">
    <input id="focus-addr" value="0x0020" size="8">
    <input id="focus-len" value="1" size="3">
    <button id="btn-focus">Enfocar</button>
    <span class="muted" id="focus-note">detenido</span>
  </div>
  <div class="panel pad" id="focus-panel" hidden>
    <div id="focus-chart"></div>
    <div class="row" id="focus-bits" style="margin-top:10px"></div>
  </div>

  <h2>Bloque manual</h2>""")

# --- estado y render --------------------------------------------------------
s = s.replace("""/* ============================================================= detalle === */""",
"""/* ================================================================ foco ===
   Muestreo rápido de una sola dirección. Las muestras llegan en lote desde el
   anillo del servidor, así que el gráfico tiene la resolución real del enlace
   y no la del navegador. */
let focusOn = false;

function renderFocus(f) {
  const panel = $('#focus-panel');
  if (!f) {
    panel.hidden = true;
    $('#focus-note').textContent = focusOn ? 'esperando datos…' : 'detenido';
    return;
  }
  panel.hidden = false;
  const pts = f.samples.map(s => ({ x: s.t, y: s.v[0] }));
  const span = pts.length > 1 ? pts[pts.length-1].x - pts[0].x : 0;
  $('#focus-note').textContent =
    `0x${f.address.toString(16).toUpperCase().padStart(4,'0')} · ${f.hz} Hz · `
    + `${f.samples.length} muestras en ${span.toFixed(1)}s`;

  lineChart($('#focus-chart'), [{ pts }], {
    dec: 0, unit: 'valor crudo', height: 150, minRange: 8,
    xlo: '0s', xhi: span.toFixed(1) + 's', xlabel: v => v.toFixed(2) + 's' });

  // Vista por bit: si el TPS de este motor es un INTERRUPTOR (contactos de
  // ralentí y plena carga), la señal es uno o dos bits, no un valor que sube.
  // Un gráfico de byte lo escondería; una traza por bit no.
  const last = f.samples[f.samples.length - 1].v[0];
  let html = '<span class="muted" style="min-width:104px">bits ahora</span>';
  for (let b = 7; b >= 0; b--) {
    const on = (last >> b) & 1;
    const flips = f.samples.slice(1).filter((s, i) =>
      ((s.v[0] >> b) & 1) !== ((f.samples[i].v[0] >> b) & 1)).length;
    html += `<span class="bitcell ${on ? 'on' : ''}" title="bit ${b} · ${flips} flancos">
      <b>${b}</b>${on ? 1 : 0}<i>${flips}</i></span>`;
  }
  $('#focus-bits').innerHTML = html;
}

$('#btn-focus').onclick = () => {
  focusOn = !focusOn;
  $('#btn-focus').textContent = focusOn ? '■ Detener foco' : 'Enfocar';
  $('#btn-focus').className = focusOn ? 'rec' : '';
  if (focusOn) act('focus_start', {
    address: parseInt($('#focus-addr').value, 16) || 0,
    length: parseInt($('#focus-len').value, 10) || 1 });
  else act('focus_stop');
};

/* ============================================================= detalle === */""")

