// Verifica la búsqueda guiada a nivel de BIT, con el sentido invertido que
// tiene un contacto de ralentí: cerrado (1) en ralentí, abierto (0) al acelerar.
let ramCand = null, ramBase = null, ramGran = 'bit';
const bitOf = (b, i) => (b[i >> 3] >> (i & 7)) & 1;
const unitCount = b => b.length * 8;
const unitVal = (b, i) => bitOf(b, i);
const allUnits = b => { const s = new Set(); for (let i = 0; i < unitCount(b); i++) s.add(i); return s; };
function mark(b) { ramBase = b.slice(); if (ramCand === null) ramCand = allUnits(b); }
function filter(mode, b) {
  if (ramCand === null) ramCand = allUnits(b);
  const keep = new Set();
  ramCand.forEach(i => {
    const d = unitVal(b, i) - unitVal(ramBase, i);
    if ((mode==='up'&&d>0)||(mode==='down'&&d<0)||(mode==='chg'&&d!==0)||(mode==='same'&&d===0)) keep.add(i);
  });
  ramCand = keep; ramBase = b.slice();
}
const name = i => `0x00${(i>>3).toString(16).toUpperCase().padStart(2,'0')}.${i&7}`;

// byte 2 bit 4 = contacto de ralentí (1 en ralentí, 0 acelerando).
// byte 0 = contador libre. byte 1 bit 0 = ruido. byte 3 = constante.
const idle    = [0, 0b00000001, 0b00010000, 0x55];
const gas     = [0, 0b00000000, 0b00000000, 0x55];
const idle2   = [0, 0b00000001, 0b00010000, 0x55];
const gas2    = [0, 0b00000001, 0b00000000, 0x55];
let ctr = 0;
const withCtr = a => { const c = a.slice(); c[0] = (ctr++ * 37) & 0xFF; return c; };

mark(withCtr(idle));
filter('down', withCtr(gas));    // acelero: el contacto CAE
console.log('tras "bajaron" :', [...ramCand].map(name).join(' '));
filter('up',   withCtr(idle2));  // suelto: vuelve a cerrar
console.log('tras "subieron":', [...ramCand].map(name).join(' '));
filter('down', withCtr(gas2));   // acelero otra vez
console.log('tras "bajaron" :', [...ramCand].map(name).join(' '));
const ok = ramCand.size === 1 && ramCand.has(2*8 + 4);
console.log('\n' + (ok ? 'BUSQUEDA POR BIT OK — converge a 0x0002.4 (contacto de ralentí)'
                       : 'FALLA: quedaron ' + [...ramCand].map(name)));
process.exit(ok ? 0 : 1);
